  static int global(Map<String,Object> p)throws Exception{int global=n(p.get("global.midi.channel"));require(n(p.get("global.midi.over.usb.c"))>0&&global>=1&&global<=16&&p.containsKey("global.midi.bcchannel")&&n(p.get("global.midi.bcchannel"))!=global,"Use a separate global MIDI channel and enable USB-C MIDI");for(String key:MIDI)require(p.containsKey(key)&&n(p.get(key))!=global,"Use separate global and Matrix MIDI channels");return global;}
