  State set(State expected,int output,int source,int field,int value,Sender sender)throws Exception{cc(source,field);require(value>=0&&value<=127&&(field<2||value==127),"Invalid Matrix command");State before=read();require(output>=1&&output<=3&&expected.origin.equals(s.origin)&&deep(expected.property,before.property)&&before.linked==0,"Matrix changed; refresh before editing");Strip target=before.strip(output,source);require(target.enabled,"This Matrix strip is not available");int channel=channels(midi())[output-1];String key=key(output,source,field);Object old=get(target.raw,FIELD[field]);synchronized(this){Integer prior=lastMIDI.get(key);if(field<2&&prior!=null&&(prior==value||field==1&&panValue(prior)==panValue(value)))return before;lastMIDI.remove(key);}backup(before);long mark;synchronized(this){mark=revision;}sender.send("strip",output,source,field,value,channel);await(key,mark);State after=read();Strip actual=after.strip(output,source);if(field>=2)require(b(get(actual.raw,FIELD[field]))!=b(old),"Matrix toggle not confirmed; no retry sent");if(field==1)require(Math.abs(actual.pan()-panValue(value))<.00001,"Matrix pan not confirmed");require(deep(preserved(before.property,output,source,field,false),preserved(after.property,output,source,field,false)),"Other Matrix settings changed; refresh before editing");synchronized(this){lastMIDI.put(key,value);}return after;}
  void await(String key,long mark)throws Exception{long deadline=System.nanoTime()+800_000_000L;while(true){synchronized(this){if(receipts.getOrDefault(key,0L)>mark)return;}require(!s.closed,"Disconnected");require(System.nanoTime()<deadline,"Stadium did not confirm this Matrix control. Nothing was retried; refresh before editing");Thread.sleep(8);}}
  State clear(State expected,int output,Sender sender)throws Exception{State before=read();require(expected.origin.equals(s.origin)&&deep(expected.property,before.property)&&before.linked==0,"Matrix changed; refresh before clearing solos");int channel=channels(midi())[output-1];List<Integer> active=new ArrayList<>();for(Strip row:before.strips(output))if(row.solo())active.add(row.id);if(active.isEmpty())return before;backup(before);long mark;synchronized(this){mark=revision;lastMIDI.clear();}sender.send("clearSolos",output,0,0,127,channel);for(int id:active)await(key(output,id,3),mark);State after=read();for(Strip strip:after.strips(output))require(!strip.solo(),"Clear Solos unconfirmed");require(deep(preserved(before.property,output,-1,3,true),preserved(after.property,output,-1,3,true)),"Other Matrix settings changed during Clear Solos");return after;}
  void panel(int output,boolean close,Sender sender)throws Exception{require(output>=1&&output<=3,"Invalid Matrix output");int channel=global(midi());int[] sequence=close?new int[]{output%3+1,output,output}:new int[]{output%3+1,output};for(int i=0;i<sequence.length;i++){require(global(midi())==channel&&!s.closed,"Matrix routing changed");int dest=sequence[i];long mark;synchronized(this){mark=revision;}sender.send("panel",dest,0,0,dest+6,channel);long deadline=System.nanoTime()+1_500_000_000L;while(true){synchronized(this){if(panels.getOrDefault(dest,0L)>mark)break;}require(!s.closed&&System.nanoTime()<deadline,"Stadium output selection not confirmed; no retry sent");Thread.sleep(8);}if(i+1<sequence.length)Thread.sleep(120);}}
